#!/usr/bin/env python3
"""Install NukeFire Client Milestone 1.4c Tab Groups safely."""

from __future__ import annotations

import base64
import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import zlib

MILESTONE = "Milestone 1.4c — Tab Groups"
BASELINE_HASHES = {'AGENTS.md': '13ee2a0f430e242c8ff6fc8ce41b65941bdce7107a0b1f8d3cb468ee80bd881d',
 'BUILD-MILESTONE.txt': 'c1a51a46bc26bd596004cee9a413de47bdf053b0ad948335d86619d497cf9f70',
 'CHANGELOG.md': 'cb10cd173a3d33ad39324635109e70806096546b97578fff7384ab3d0324771b',
 'README.md': 'eacdf3d9c8936562696f96f682b404f4c1e08076b770eb1b7de4a8da011a9a75',
 'docs/ARCHITECTURE.md': 'e3a7bd45bc6fc4a49752d4e2ebfcdfa704dc48b54d9a331cf33880a58724c21f',
 'docs/PROJECT_LEDGER.md': '1c00137270fb99dc32de9e9e4ee1dc02c1c81647eba5279e2974215cb1cd93ad',
 'docs/ROADMAP.md': '71d52be57266cd90f81116dd215d5012c06de7c466c8d104eece2a10528ebe42',
 'renderer/index.html': '41bb1d9c937d09d940c17596539238bdcde21a33758f609b948313c6bc7cbc4f',
 'renderer/renderer.js': '1d4243bfa6d7aa0a0b91133bdc5b513c7e12ff512716ad0f08b980d405f47ce5',
 'renderer/styles.css': 'dd1d7097ec9ec57584f9f3bfecda68b7af2a03d47d8414ab7e9cebba9f500308',
 'src/settings-store.js': '927402aec6293e7e2e621191f00e328da690ab0bdf98bdc19fa3239c48bc0cf1',
 'test/settings-store.test.js': '719ee5828e8df8f63ac46e9765b645534f9d2ded4e2be604daee68207a079c2b',
 'test/tab-groups.test.js': None}
TARGET_HASHES = {'AGENTS.md': '292f2841cf29d29a8488e14f5d243be166c099e848226159f474ea6b581fd8ea',
 'BUILD-MILESTONE.txt': '4c7aca774c1879cf65a2fa0dfc5b3007d3eb5ea87606bf01315b77311d095bae',
 'CHANGELOG.md': 'e9aacaa6ace4b94cac48badb9b59f9ea36387366df68995da15e98ff2735c2ae',
 'README.md': 'eab62ecb56a65b69b69a8c1347993eea5ab0c6630a309d5cb08c07bdbe617327',
 'docs/ARCHITECTURE.md': 'a38d1598537479879d2fc868ad9bed51e16dc7758649aa1c0e6ffbf9830463f7',
 'docs/PROJECT_LEDGER.md': '806dde61c9b466428ee397ba71db00842bfc641075056157439f21dc6c4eee67',
 'docs/ROADMAP.md': 'aa87c1bf0b2b8c507531139d16091215426ef1f6ea3ec19f845c33e7ab00f422',
 'renderer/index.html': 'a37c7e1579fc4cacce9e9de84016f8e0250c3d8af76e08ecaa5ae57801ced946',
 'renderer/renderer.js': 'eea6eee407311868fed6f0b1259c4fe6a58ad5dffef226fa74168c697ba0c6f8',
 'renderer/styles.css': '1b27ea228ed43a2f3ed58dbfbee50c2fa8f9eb21a5ae63a521902bc52d1cefbc',
 'src/settings-store.js': '70489f0bf17dec8d137949ba24acf2e81b48077709ec32e58b41231241984496',
 'test/settings-store.test.js': '7b8d57ddb8e759cad884139b7a01b368dca636a1c4b4c72009e4ede13148f2bc',
 'test/tab-groups.test.js': 'f4970558985022f2c56bd132e624c8b8fed57b06c207ac8de47395558204cee2'}
PAYLOAD = ''


def digest(path: Path) -> str | None:
    if not path.exists():
        return None
    return hashlib.sha256(path.read_bytes()).hexdigest()


def load_payload() -> dict[str, bytes]:
    packed = zlib.decompress(base64.b64decode(PAYLOAD.encode("ascii")))
    encoded = json.loads(packed.decode("utf-8"))
    return {name: base64.b64decode(content) for name, content in encoded.items()}


def verify_project_root(root: Path) -> None:
    package_path = root / "package.json"
    if not package_path.is_file():
        raise RuntimeError(
            "Place this installer beside package.json and run it from the "
            "NukeFire client repository."
        )
    package = json.loads(package_path.read_text(encoding="utf-8"))
    if package.get("name") != "nukefire-mac-client":
        raise RuntimeError("This does not appear to be the NukeFire Mac client repository.")


def current_state(root: Path) -> dict[str, str | None]:
    return {name: digest(root / name) for name in TARGET_HASHES}


def report_mismatch(current: dict[str, str | None]) -> None:
    print(
        "The installer stopped because the source is not the confirmed "
        "Milestone 1.4b Resizable Dock Regions baseline.",
        file=sys.stderr,
    )
    print("No files were changed. Unexpected paths:", file=sys.stderr)
    for name, expected in BASELINE_HASHES.items():
        if current.get(name) != expected:
            actual = current.get(name) or "missing"
            wanted = expected or "absent"
            print(
                f"  {name}\n    expected: {wanted}\n    found:    {actual}",
                file=sys.stderr,
            )


def run_verify(root: Path) -> None:
    print("\nRunning npm run verify...\n")
    completed = subprocess.run(["npm", "run", "verify"], cwd=root)
    if completed.returncode != 0:
        raise RuntimeError("npm run verify failed")


def main() -> int:
    root = Path(__file__).resolve().parent
    verify_project_root(root)
    current = current_state(root)

    if current == TARGET_HASHES:
        print(f"{MILESTONE} is already installed.")
        run_verify(root)
        return 0

    if current != BASELINE_HASHES:
        report_mismatch(current)
        return 2

    payload = load_payload()
    backup_root = Path(tempfile.mkdtemp(prefix=".milestone-1.4c-backup-", dir=root))
    existing_paths: set[str] = set()

    try:
        for name in payload:
            source = root / name
            if source.exists():
                existing_paths.add(name)
                backup = backup_root / name
                backup.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(source, backup)

        for name, content in payload.items():
            destination = root / name
            destination.parent.mkdir(parents=True, exist_ok=True)
            temporary = destination.with_name(f".{destination.name}.milestone-1.4c.tmp")
            temporary.write_bytes(content)
            if destination.exists():
                os.chmod(temporary, destination.stat().st_mode)
            else:
                os.chmod(temporary, 0o644)
            os.replace(temporary, destination)

        installed = current_state(root)
        if installed != TARGET_HASHES:
            raise RuntimeError(
                "Installed files did not match the verified Milestone 1.4c payload"
            )

        run_verify(root)
    except Exception as error:
        print(f"\nInstallation failed: {error}", file=sys.stderr)
        print("Restoring the confirmed Milestone 1.4b files...", file=sys.stderr)
        for name in payload:
            destination = root / name
            backup = backup_root / name
            if name in existing_paths and backup.exists():
                destination.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(backup, destination)
            elif destination.exists():
                destination.unlink()
        shutil.rmtree(backup_root, ignore_errors=True)
        return 1

    shutil.rmtree(backup_root, ignore_errors=True)
    print(f"\n{MILESTONE} installed successfully.")
    print("Panels can now be combined into keyboard-accessible tab groups within each dock.")
    print("The terminal output, command input, scrolling, pagination, Telnet, and GMCP transport were not rewritten.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
